DROP POLICY IF EXISTS "Staff can insert lead activities" ON public.lead_activities;
CREATE POLICY "Staff can insert lead activities" ON public.lead_activities FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'approver'::app_role) OR has_role(auth.uid(), 'sales'::app_role) OR has_role(auth.uid(), 'writer'::app_role));
DROP POLICY IF EXISTS "Staff can update lead activities" ON public.lead_activities;
CREATE POLICY "Staff can update lead activities" ON public.lead_activities FOR UPDATE TO authenticated USING (has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'approver'::app_role) OR has_role(auth.uid(), 'sales'::app_role)) WITH CHECK (has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'approver'::app_role) OR has_role(auth.uid(), 'sales'::app_role));
DROP POLICY IF EXISTS "Staff can delete lead activities" ON public.lead_activities;
CREATE POLICY "Staff can delete lead activities" ON public.lead_activities FOR DELETE TO authenticated USING (has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'approver'::app_role) OR has_role(auth.uid(), 'sales'::app_role));